def figure(s):
    pts = ''.join(f'<li>{e(p)}</li>' for p in s['points'])
    meta = (f'<div class="sh"><span class="sid">{s["id"]}</span><b>{e(s["title"])}</b><span class="ph-tag">{e(PHASE_NAME[s["phase"]])}</span></div>')
    if s['kind']=='web':
        return (f'<figure class="fig web">{meta}<div class="fm"><div><span class="lbl">사용자</span> {e(s["who"])}<br><span class="lbl">필요 권한</span> {e(s["perms"])}</div><div>{e(s["purpose"])}</div></div>'
                f'<ul class="fp">{pts}</ul><div class="zw" data-s="0.66"><div class="zin scr">{s["html"]}</div></div></figure>')
    return (f'<figure class="fig ph">{meta}<div class="zp" data-s="0.56"><div class="zin scr">{s["html"]}</div></div>'
            f'<div class="fc"><span class="lbl">사용자</span> {e(s["who"])}<br>{e(s["purpose"])}<ul class="fp">{pts}</ul></div></figure>')

def gallery(phase):
    items = [s for s in S if s['phase']==phase]
    web = [s for s in items if s['kind']=='web']; ph = [s for s in items if s['kind']=='phone']
    out = ''
    if web: out += ''.join(figure(s) for s in web)
    if ph:
        out += '<div class="phgrid">'+''.join(figure(s) for s in ph)+'</div>'
    return out

def chap(n, title, body, new_page=True):
    cn = f'<span class="cn">{n}</span>' if str(n).isdigit() else ''
    return f'<section class="chap{" np" if new_page else ""}" data-n="{n}"><h1 id="c{n}">{cn}{e(title)}</h1>{body}</section>'

def build(toc_pages=None, part='all'):
    toc_pages = toc_pages or {}
    cover = f'''<section class="cover"><div class="cv-top">개발 제안서</div><h1 class="cv-title">OIO 캐스팅 플랫폼<br>구축 제안</h1>
<div class="cv-sub">직원 업무 시스템에서 출연자 인재 데이터베이스까지<br>단계별로 완성하는 통합 플랫폼</div>
<div class="cv-meta"><table><tr><td>제출 대상</td><td>OIO 대표 및 경영진 · 투자 검토자</td></tr><tr><td>제안자</td><td>{CFG['proposer']}</td></tr><tr><td>제출일</td><td>{CFG['submit_date']}</td></tr><tr><td>문서 버전</td><td>{CFG['version']}</td></tr></table></div>
<div class="cv-note">본 문서는 제안 목적으로 작성되었으며 법률·세무 자문이 아닙니다. 외부 서비스 가격·정책·법령 정보는 작성 시점의 2차 자료에 근거하므로 계약 전 공식 출처로 재확인합니다. 금액 항목은 비워 두었습니다.</div></section>'''
    toc_rows = ''.join(f'<tr><td class="tn">{n if str(n).isdigit() else ""}</td><td>{e(t)}</td><td class="tp">{toc_pages.get(str(n),"")}</td></tr>' for n,t in CH_TITLES)
    toc = f'<section class="toc np"><h1 class="tt">목차</h1><table class="tocT">{toc_rows}</table></section>'
    if part=='cover': return cover
    return (toc if part=='body' else cover+toc) + ''.join(chapters_html())

